/**
 * The generated "Measurements (S07c)" section of data/landmarks/SOURCES.md: every measured
 * landmark's sources, dimensions, readability scales and the shipped levels from its lock, so
 * the record of where each number came from cannot drift from the files the build used.
 *
 * Bullet lists rather than tables: Prettier re-aligns tables, and the section must be
 * byte-stable for `npm run landmarks:check`.
 */
import type {
  BlenderLock,
  LandmarkMeasurements,
} from '../../src/lib/data/schemas/landmarkBlender.ts'

export const SECTION_START =
  '<!-- measurements:start (generated by npm run landmarks:blender; do not edit by hand) -->'
export const SECTION_END = '<!-- measurements:end -->'

export interface MeasuredLandmark {
  readonly measurements: LandmarkMeasurements
  readonly lock: BlenderLock | undefined
}

type Dimension = LandmarkMeasurements['dimensions'][string]

function value(dimension: Dimension): string {
  if ('valueM' in dimension) return `${dimension.valueM} m`
  if ('widthM' in dimension) return `${dimension.widthM} × ${dimension.depthM} m`
  return `${dimension.count} × ${dimension.diameterM} m diameter`
}

function landmarkSection({ measurements, lock }: MeasuredLandmark): string[] {
  const lines = [`### ${measurements.id}`, '', `Retrieved ${measurements.retrieved}. Sources:`, '']
  for (const source of measurements.sources) {
    lines.push(`- \`${source.id}\`: ${source.title}, ${source.licence}, <${source.url}>`)
  }
  lines.push('', 'Dimensions:', '')
  for (const [key, dimension] of Object.entries(measurements.dimensions)) {
    lines.push(`- \`${key}\`: ${value(dimension)} (${dimension.source}): ${dimension.note}`)
  }
  const scales = Object.entries(measurements.readabilityScale).filter(
    (entry): entry is [string, number] => typeof entry[1] === 'number',
  )
  lines.push(
    '',
    `Readability scale (drawn width ÷ true width): ${scales.map(([k, v]) => `${k} ×${v}`).join(', ')}.`,
  )
  if (lock === undefined) {
    lines.push('', 'Not built yet.')
  } else {
    lines.push(
      '',
      `Built with Blender ${lock.blender.version} (${lock.blender.buildHash}) under caps ` +
        `low ${lock.caps.low} / mid ${lock.caps.mid} / high ${lock.caps.high} triangles:`,
      '',
    )
    for (const level of lock.levels) {
      lines.push(
        `- L${level.level}: ${level.triangles} triangles, ${level.bytes} bytes (\`${level.file}\`)`,
      )
    }
  }
  return [...lines, '']
}

export function renderSection(landmarks: readonly MeasuredLandmark[]): string {
  return [
    SECTION_START,
    '',
    '## Measurements (S07c)',
    '',
    'Blender-built models (`scripts/blender/`, DEC-25) take their dimensions from',
    '`data/landmarks/measurements/<id>.json`: CC0 or public-domain numbers only (Wikidata,',
    'HAER/HABS, NPS, public-domain texts), never traced from photos. A value marked `estimate` or',
    '`derived` says in its note how it was set. Thin members (cables, suspenders, lamps) are drawn',
    'wider than they are, by the readability scale, so they read at game distance. The models',
    'are ours: no third-party licence applies to them.',
    '',
    ...landmarks.flatMap(landmarkSection),
    SECTION_END,
  ].join('\n')
}

/** `markdown` with its generated section replaced (or appended when it has none yet). */
export function withSection(markdown: string, section: string): string {
  const start = markdown.indexOf(SECTION_START)
  const end = markdown.indexOf(SECTION_END)
  if (start === -1 || end === -1) return `${markdown.trimEnd()}\n\n${section}\n`
  return `${markdown.slice(0, start)}${section}${markdown.slice(end + SECTION_END.length)}`
}
